parameters.jsonBody:
={
  "model": "openai/gpt-oss-120b",
  "messages": [
    {
      "role": "system",
      "content": "You are an enterprise customer support AI triage agent. Analyze the customer inquiry and output strictly valid JSON with keys: category (billing, technical, account, general), priority (low, medium, high, urgent), sentiment (positive, neutral, negative, frustrated), summary (1-2 sentences), drafted_response (single-paragraph professional, empathetic response with no raw newlines or special control characters), confidence_score (number 0.0 to 1.0), requires_escalation (true or false). Only output pure JSON, nothing else."
    },
    {
      "role": "user",
      "content": "Subject: {{ $json.subject }}\nBody: {{ $json.message }}\nCustomer: {{ $json.customer_email }}"
    }
  ],
  "response_format": { "type": "json_object" },
  "temperature": 0.2
}

parameters.jsCode:
const rawContent = $json.choices[0].message.content;
let parsed = {};
try {
  parsed = JSON.parse(rawContent);
} catch (e) {
  parsed = {
    category: 'general',
    priority: 'medium',
    drafted_response: rawContent,
    confidence_score: 0.8,
    requires_escalation: false,
    sentiment: 'neutral'
  };
}

const ticket = $('FastAPI: Validate & Intake Ticket').first().json;

// Format exactly according to our Supabase database schema
const ticketPayload = {
  external_id: ticket.external_id || ('ext-' + Date.now()),
  customer_email: ticket.customer_email,
  customer_name: ticket.customer_name || 'Customer',
  subject: ticket.subject,
  message: ticket.message,
  category: (parsed.category || 'general').toLowerCase(),
  priority: (parsed.priority || 'medium').toLowerCase(),
  status: 'draft_ready',
  metadata: {
    ai_draft: parsed.drafted_response || 'Thank you for reaching out.',
    confidence: Number(parsed.confidence_score || 0.85),
    requires_escalation: Boolean(parsed.requires_escalation),
    sentiment: parsed.sentiment || 'neutral'
  }
};

return [{
  json: {
    ticket_payload: ticketPayload,
    triage_result: parsed
  }
}];
